-- TFJ : images du F4 (icones des onglets, sceaux des arbres, filigrane, grain). Dessinees pour TFJ.
-- Ecrites dans data/tfj_f4/ puis chargees comme materiaux.
TFJ_F4 = TFJ_F4 or {}
TFJ_F4.Img = TFJ_F4.Img or {}
local VERSION = 2
local tB64 = {
    ["filigrane"] = "",
    ["grain"] = "",
    ["onglet_clans"] = "",
    ["onglet_classes"] = "",
    ["onglet_kekkei"] = "",
    ["onglet_natures"] = "",
    ["onglet_styles"] = "",
    ["sceau_clan"] = "",
    ["sceau_doton"] = "",
    ["sceau_futon"] = "",
    ["sceau_guerrier"] = "",
    ["sceau_katon"] = "",
    ["sceau_kekkei"] = "",
    ["sceau_kenjutsu"] = "",
    ["sceau_medicale"] = "",
    ["sceau_mirage"] = "",
    ["sceau_raiton"] = "",
    ["sceau_robustesse"] = "",
    ["sceau_shinobi"] = "",
    ["sceau_suiton"] = "",
    ["sceau_taijutsu"] = "",
    ["shuriken"] = "",
}
file.CreateDir("tfj_f4")
for sNom, sB64 in pairs(tB64) do
    local sChemin = "tfj_f4/" .. sNom .. "_v" .. VERSION .. ".png"
    if not file.Exists(sChemin, "DATA") then file.Write(sChemin, util.Base64Decode(sB64)) end
    TFJ_F4.Img[sNom] = Material("../data/" .. sChemin, sNom == "grain" and "noclamp smooth" or "smooth mips")
end
